<?php require '../config.php';if(admin()){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$q=db()->prepare('SELECT * FROM admins WHERE email=?');$q->execute([trim($_POST['email']??'')]);$a=$q->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin']=$a['id'];header('Location:index.php');exit;}$err='Invalid credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin login · FeatureBoard</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><div class="login"><div class="loginbox"><div class="brand"><span class="mark">F</span> FeatureBoard</div><h1>Admin sign in</h1><p style="color:var(--muted)">Review ideas, manage roadmap status, and reply to customers.</p><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="field"><label>Email</label><input class="input" type="email" name="email" value="<?=e(ADMIN_EMAIL)?>" required></div><div class="field"><label>Password</label><input class="input" type="password" name="password" value="<?=e(ADMIN_PASSWORD)?>" required></div><button class="btn orange" style="width:100%">Sign in</button></form><p style="font-size:12px;color:var(--muted);margin-top:18px">Default: <?=e(ADMIN_EMAIL)?> / <?=e(ADMIN_PASSWORD)?></p></div></div></body></html>
